        const detailStr = detail.length > 0 ? ` — ${detail.join(', ')}` : '';
        status.textContent = `Materializing chunk ${processed}/${total}${cxStr}${detailStr}`;
        footer.textContent = `${50 + Math.floor((processed / total) * 50)}%`;
